/**
 * Whether the app is running inside a Capacitor shell. The shell defines
 * `window.Capacitor` before the page script runs, so the check is
 * synchronous and needs no import, which keeps the browser bundle free of
 * native code.
 */
interface CapacitorGlobal {
  isNativePlatform(): boolean;
  getPlatform(): string;
}

function runtime(): CapacitorGlobal | undefined {
  return (window as Window & { Capacitor?: CapacitorGlobal }).Capacitor;
}

export function isNativeShell(): boolean {
  return runtime()?.isNativePlatform() === true;
}

/** "ios" or "android" inside a shell; "web" anywhere else. */
export function shellPlatform(): 'ios' | 'android' | 'web' {
  const name = runtime()?.getPlatform();
  return name === 'ios' || name === 'android' ? name : 'web';
}

/**
 * Whether the app is running in the Lexpad desktop app's main window. The
 * desktop app injects its configuration (`window.__LEXPAD_CONFIG`, platform
 * `desktop`) before the page script runs, and the window has Tauri's IPC.
 * Both must be there: the configuration alone could be set by anything.
 */
export function isDesktopShell(): boolean {
  const w = window as Window & { __LEXPAD_CONFIG?: { platform?: string }; __TAURI_INTERNALS__?: unknown };
  return w.__LEXPAD_CONFIG?.platform === 'desktop' && typeof w.__TAURI_INTERNALS__ === 'object';
}
