/**
 * What "Lexpad everywhere" knows, and where it keeps it.
 *
 * The server is the only one who knows what this account has used on other
 * devices and what it did with the cards on Today, so both are read from
 * the API — and copied into IndexedDB meta, so the hub and the card draw
 * from local data on the first frame and say "as of" when offline. Every
 * write here happens outside a live query: a write inside one retriggers
 * the query that made it.
 */
import { dayIndex } from '@lexpad/core';
import { me } from '@/api/endpoints.js';
import type { ApiNudgeEvent, ApiNudgeId, ApiNudgeView, ApiSurfaceStatus } from '@/api/types.js';
import { db, getMeta, setMeta, type LexpadDb } from '@/db/schema.js';
import { newId } from '@/lib/id.js';
import { platform } from '@/lib/platform/index.js';

/** Reads every surface from the server and keeps a copy. Throws what the client threw. */
export async function refreshSurfaces(database: LexpadDb = db): Promise<ApiSurfaceStatus[]> {
  const list = await me.surfaces();
  await setMeta('surfaces', { at: new Date().toISOString(), list }, database);
  return list;
}

/** Reads the cards' rules and history from the server and keeps a copy. */
export async function refreshNudges(database: LexpadDb = db): Promise<ApiNudgeView> {
  const view = await me.nudges();
  await setMeta('nudges', { at: new Date().toISOString(), view }, database);
  return view;
}

/**
 * Records what happened to a card. The copy is updated with the server's
 * answer; offline, the event is lost rather than queued, which errs on the
 * side of showing the card less, never more: a lost "shown" is one more
 * chance later, a lost "Not now" is the same card next session, which the
 * "never twice in a row" rule then stops.
 */
export async function recordNudge(
  id: ApiNudgeId,
  event: ApiNudgeEvent,
  session: string,
  database: LexpadDb = db,
): Promise<void> {
  const view = await me.recordNudge(id, event, session);
  await setMeta('nudges', { at: new Date().toISOString(), view }, database);
}

/**
 * The current app session: the app opened after `gapMinutes` away starts a
 * new one. "Away" is measured from the last time this was asked, which the
 * card asks whenever Today is shown and the app comes back to the front.
 */
export async function touchAppSession(
  gapMinutes: number,
  now: number = Date.now(),
  database: LexpadDb = db,
): Promise<string> {
  const current = await getMeta('appSession', database);
  const fresh = current === null || now - current.lastActiveAt > gapMinutes * 60_000;
  const id = fresh ? newId() : current.id;
  await setMeta('appSession', { id, lastActiveAt: now }, database);
  return id;
}

/**
 * Notes that the app is still in use without starting a new session: called
 * as the app goes to the background, so "away" is measured from leaving
 * rather than from the last time Today was opened.
 */
export async function keepAppSessionAlive(now: number = Date.now(), database: LexpadDb = db): Promise<void> {
  const current = await getMeta('appSession', database);
  if (current !== null) await setMeta('appSession', { id: current.id, lastActiveAt: now }, database);
}

/** Counts one more use of "Paste a text" or "Read a text" on this device. */
export async function notePasteUse(database: LexpadDb = db): Promise<void> {
  await database.transaction('rw', database.meta, async () => {
    await setMeta('pasteUses', (await getMeta('pasteUses', database)) + 1, database);
  });
}

/** What this device knows about how the account uses Lexpad, for the triggers. */
export interface LocalSignals {
  /** Words the learner added themselves (typed, or typed and filled by AI). */
  typedWords: number;
  /** On how many different days those were added. */
  typedDays: number;
  /** Every word in every notebook. */
  words: number;
  /** Days with at least one card practised. */
  practiceDays: number;
  pasteUses: number;
}

/**
 * Reads the signals. "Typed" is `manual` or `ai`: the extension marks its
 * words the same way, which does not matter for the extension card (it is
 * only shown to somebody who never used the extension), and words from
 * "Paste a text" do too — there is no "via" on a word yet to tell them apart.
 */
export async function loadSignals(timeZone: string, database: LexpadDb = db): Promise<LocalSignals> {
  const [words, stats, pasteUses] = await Promise.all([
    database.words.toArray(),
    database.dayStats.toArray(),
    getMeta('pasteUses', database),
  ]);
  const typed = words.filter((word) => word.source === 'manual' || word.source === 'ai');
  const days = new Set(typed.map((word) => dayIndex(new Date(word.createdAt), timeZone)));
  return {
    typedWords: typed.length,
    typedDays: days.size,
    words: words.length,
    practiceDays: stats.filter((day) => day.reviewed > 0).length,
    pasteUses,
  };
}

/**
 * Where somebody arrived from, when it was an assistant: a sign-up that came
 * from ChatGPT or Claude is the strongest sign that the connector would help.
 * It must survive the sign-up itself, which starts this device's database
 * afresh, so it is one of the few things kept in `platform.prefs`; it holds
 * a word ("chatgpt" or "claude"), never the address.
 */
const ARRIVAL_KEY = 'lexpad.arrivedFrom';

export type Arrival = 'chatgpt' | 'claude';

/** The assistant a referrer address belongs to, if any. */
export function arrivalFrom(referrer: string): Arrival | undefined {
  let host: string;
  try {
    host = new URL(referrer).hostname;
  } catch {
    return undefined;
  }
  if (host === 'chatgpt.com' || host.endsWith('.chatgpt.com') || host === 'chat.openai.com') return 'chatgpt';
  if (host === 'claude.ai' || host === 'claude.com' || host.endsWith('.claude.ai')) return 'claude';
  return undefined;
}

/** Remembers that this signed-out visit came from an assistant. */
export function noteArrival(referrer: string): void {
  const from = arrivalFrom(referrer);
  if (from !== undefined) platform.prefs.set(ARRIVAL_KEY, from);
}

/** The assistant this device's visit came from, if it did. */
export function arrival(): Arrival | undefined {
  const value = platform.prefs.get(ARRIVAL_KEY);
  return value === 'chatgpt' || value === 'claude' ? value : undefined;
}
