/**
 * The platform inside the Capacitor shells. Every plugin is loaded on first
 * use, so this file can sit in the shared bundle without the browser build
 * ever downloading native bridge code.
 */
import { SpeechRecognition } from '@capacitor-community/speech-recognition';
import { registerPlugin } from '@capacitor/core';
import type { FirebaseMessagingPlugin, Importance } from '@capacitor-firebase/messaging';
import { t } from '@/i18n/index.js';
import { backButtonAction, isFirstEntry } from './backButton.js';
import { outcomeOf, worthRetrying } from './speechErrors.js';
import { shellPlatform } from './detect.js';
import type {
  Env,
  Haptics,
  Lifecycle,
  NativeSignIn,
  Network,
  Platform,
  Push,
  Reminders,
  WebPush,
  SecureStorage,
  Share,
  Speech,
  Tts,
} from './types.js';
import { SpeechDenied } from './types.js';
import { deviceId, prefs } from './web.js';
import { appLinkPath } from './appLink.js';
import { pushPath } from './pushLink.js';

/** The notification id the daily reminder always uses, so it replaces itself. */
/**
 * Every reminder lives in this block of ids, so a new plan can cancel all of
 * the last one without knowing its shape. Id 1 is also the repeating daily
 * reminder of builds before 1.0.43, which this clears on the first run.
 */
const REMINDER_IDS = Array.from({ length: 20 }, (_, index) => ({ id: index + 1 }));

function readEnv(): Env {
  return {
    embedded: true,
    platform: shellPlatform(),
    // The shell is built for one API; there is no same-origin fallback here.
    apiUrl: import.meta.env.VITE_API_URL ?? '',
    appVersion: import.meta.env.VITE_APP_VERSION ?? 'dev',
    deviceId: deviceId(),
    googleClientId: import.meta.env.VITE_GOOGLE_CLIENT_ID ?? '',
    appleClientId: import.meta.env.VITE_APPLE_CLIENT_ID ?? '',
    billingEnabled: import.meta.env.VITE_BILLING_ENABLED === 'true',
  };
}

/** Errors from a plugin are logged, never thrown into a screen. */
function quietly(work: Promise<unknown>): void {
  work.catch((cause: unknown) => {
    console.error('native bridge failed', cause);
  });
}

/**
 * Languages the device engine can speak, as lowercase primary tags; undefined
 * until the plugin has answered, which happens once, on the first question.
 */
let voiceLanguages: Set<string> | undefined;
let voicesAsked = false;
const voiceListeners = new Set<() => void>();

function languageOf(locale: string): string {
  return locale.toLowerCase().split(/[-_]/)[0] ?? '';
}

function askVoices(): void {
  if (voicesAsked) return;
  voicesAsked = true;
  quietly(
    import('@capacitor-community/text-to-speech').then(async ({ TextToSpeech }) => {
      const { languages } = await TextToSpeech.getSupportedLanguages();
      // An empty answer means the engine would not say, not that it is mute.
      if (languages.length === 0) return;
      voiceLanguages = new Set(languages.map(languageOf));
      for (const listener of voiceListeners) listener();
    }),
  );
}

/**
 * How long to give the recognition service to finish binding before the
 * second attempt. Long enough for the bind to land on a phone that has not
 * used speech since it booted, short enough that nobody reads it as the app
 * having stalled: the listening overlay stays up throughout, so this is a
 * pause inside one continuous "listening", not a second failure.
 */
const SETTLE_MS = 400;

const pause = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Which listen is running, and which one stopping was last asked about.
 *
 * A retry has to know whether the person closed *this* listen -- reopening
 * a microphone somebody has just closed would be the app arguing with them
 * -- and a plain flag could not tell that from a previous listen having
 * been closed a moment before this one started.
 */
let listenId = 0;
let stoppedId = -1;

/**
 * Speech inside the shells, through the operating system's own recogniser.
 *
 * The web implementation cannot be used here. Android's web view does
 * expose `webkitSpeechRecognition`, so the button looked ready, but there is
 * no speech service behind it in a web view: it failed with the same error a
 * refused microphone gives, and the app told people to change a setting in a
 * browser they were not using.
 */
const speech: Speech = {
  available: async () => {
    try {
      const { available } = await SpeechRecognition.available();
      return available;
    } catch {
      return false;
    }
  },

  listen: async (locale, onPartial) => {
    // Asked every time rather than remembered: the person may have refused
    // once and changed their mind, or revoked it in system settings since.
    const granted = await SpeechRecognition.requestPermissions().catch(() => undefined);
    if (granted?.speechRecognition !== 'granted') throw new SpeechDenied();

    // partialResults is deliberately off. With it on, this plugin resolves
    // start() immediately and empty and delivers the words through a
    // listener instead -- which is how the first version of this shipped
    // hearing nothing at all. Off, start() resolves once with the matches
    // and rejects with a real message, which is the whole contract this
    // needs. The live preview is not worth a result that never arrives.
    onPartial('');
    const mine = (listenId += 1);

    // Two goes at most. The second one is for a recognition service that
    // had not finished binding when the first one asked -- see the
    // NOT_READY list -- and by then it has. Anything that fails twice is a
    // real fault and is reported as one.
    for (let go = 0; ; go += 1) {
      try {
        const result = await SpeechRecognition.start({
          language: locale,
          maxResults: 1,
          partialResults: false,
          // No system dialog: the sheet is already the interface, and a
          // second one over it is a second thing to dismiss.
          popup: false,
        });
        return (result.matches?.[0] ?? '').trim();
      } catch (cause) {
        const said = cause instanceof Error ? cause.message : String(cause);
        switch (outcomeOf(said)) {
          case 'silence':
            return '';
          case 'refused':
            throw new SpeechDenied();
          default:
            break;
        }
        // Somebody who has already tapped Stop is not waiting for a second
        // attempt, and a retry there would reopen the microphone they just
        // closed.
        if (go > 0 || stoppedId === mine || !worthRetrying(said)) throw new Error(said, { cause });
        await pause(SETTLE_MS);
        if (stoppedId === mine) return '';
      }
    }
  },

  stop: () => {
    stoppedId = listenId;
    void SpeechRecognition.stop().catch(() => undefined);
  },
};

const tts: Tts = {
  available: true,
  canSpeak(locale) {
    askVoices();
    return voiceLanguages === undefined || voiceLanguages.has(languageOf(locale));
  },
  onVoicesChange(listener) {
    voiceListeners.add(listener);
    return () => {
      voiceListeners.delete(listener);
    };
  },
  speak(text, locale) {
    quietly(
      import('@capacitor-community/text-to-speech').then(async ({ TextToSpeech }) => {
        await TextToSpeech.stop();
        await TextToSpeech.speak({ text: text.replace(/\s*\/\s*/g, ' or '), lang: locale, rate: 0.9 });
      }),
    );
  },
  cancel() {
    quietly(import('@capacitor-community/text-to-speech').then(({ TextToSpeech }) => TextToSpeech.stop()));
  },
};

const haptics: Haptics = {
  correct() {
    quietly(
      import('@capacitor/haptics').then(({ Haptics, ImpactStyle }) =>
        Haptics.impact({ style: ImpactStyle.Light }),
      ),
    );
  },
  wrong() {
    quietly(
      import('@capacitor/haptics').then(({ Haptics, NotificationType }) =>
        Haptics.notification({ type: NotificationType.Error }),
      ),
    );
  },
  success() {
    quietly(
      import('@capacitor/haptics').then(({ Haptics, NotificationType }) =>
        Haptics.notification({ type: NotificationType.Success }),
      ),
    );
  },
};

/** Keychain on iOS, Keystore-backed storage on Android. */
const secure: SecureStorage = {
  async get(key) {
    const { SecureStorage } = await import('@aparajita/capacitor-secure-storage');
    return SecureStorage.getItem(key);
  },
  async set(key, value) {
    const { SecureStorage } = await import('@aparajita/capacitor-secure-storage');
    await SecureStorage.setItem(key, value);
  },
  async remove(key) {
    const { SecureStorage } = await import('@aparajita/capacitor-secure-storage');
    await SecureStorage.remove(key);
  },
};

const share: Share = {
  async file(name, mime, data) {
    // The share sheet takes a file URI, so the export is written to the
    // app's cache first; the system cleans that directory itself.
    const [{ Filesystem, Directory, Encoding }, { Share }] = await Promise.all([
      import('@capacitor/filesystem'),
      import('@capacitor/share'),
    ]);
    const text = typeof data === 'string' ? data : await new Blob([data], { type: mime }).text();
    const written = await Filesystem.writeFile({
      path: name,
      data: text,
      directory: Directory.Cache,
      encoding: Encoding.UTF8,
    });
    await Share.share({ title: name, files: [written.uri] });
  },
  async text(value) {
    const { Clipboard } = await import('@capacitor/clipboard');
    await Clipboard.write({ string: value });
  },
  async link(url, title) {
    const { Share } = await import('@capacitor/share');
    await Share.share({ title, url });
    return 'shared';
  },
};

// The plugin reports changes; the flag keeps the synchronous `online` read
// the sync worker expects. It starts from the browser's own view.
let online = navigator.onLine;
const networkListeners = new Set<(online: boolean) => void>();
const network: Network = {
  get online() {
    return online;
  },
  onChange(listener) {
    networkListeners.add(listener);
    return () => {
      networkListeners.delete(listener);
    };
  },
};

const reminders: Reminders = {
  async schedule(plan) {
    const { LocalNotifications } = await import('@capacitor/local-notifications');
    await LocalNotifications.cancel({ notifications: REMINDER_IDS });
    if (plan === null) return 'off';
    // Ask only while the answer is still open; a refusal is reported, not
    // asked again on every launch.
    let { display } = await LocalNotifications.checkPermissions();
    if (display === 'prompt' || display === 'prompt-with-rationale') {
      display = (await LocalNotifications.requestPermissions()).display;
    }
    if (display !== 'granted') return 'denied';
    const now = Date.now();
    try {
      await LocalNotifications.schedule({
        notifications: plan
          .filter((notice) => notice.at.getTime() > now)
          .map((notice) => ({
            id: notice.id,
            title: notice.title,
            body: notice.body,
            // A dated one-off rather than a repeating alarm, so every day can
            // say what is due that day. allowWhileIdle lets Android deliver it
            // through Doze. Inexact on purpose: exact alarms need a permission
            // that Android 12+ grants only in system settings, and the plugin
            // would send the user there on its own. A few minutes late is fine.
            schedule: { at: notice.at, allowWhileIdle: true },
            isExactNotification: false,
          })),
      });
    } catch {
      // The host refused to schedule (notifications switched off for the app
      // between the check and the call); that is what "denied" describes.
      return 'denied';
    }
    return 'scheduled';
  },
};

/**
 * The Android channel server notifications arrive on. The server names it in
 * every message and the manifest names it as the default, so the three must
 * agree; it is a constant because Android keys a channel by this string for
 * the life of the install.
 */
const PUSH_CHANNEL = 'lexpad_updates';

/**
 * Android's "default" importance (3): it sounds and shows in the shade but
 * does not drop down over whatever is open. News and gifts can wait for a
 * glance. Written as the number because the plugin's enum is a runtime value
 * we do not import (see `messaging` below).
 */
const PUSH_IMPORTANCE = 3 as Importance;

/**
 * Firebase Cloud Messaging, registered by name rather than imported from the
 * plugin package. The package's own entry point carries a lazy web fallback
 * that imports the Firebase JavaScript SDK; importing it would put that SDK
 * in the build (or fail it, since the SDK is not installed). Only the native
 * half is ever wanted, and the shell supplies it under this name.
 */
let messaging: FirebaseMessagingPlugin | undefined;
function fcm(): FirebaseMessagingPlugin {
  messaging ??= registerPlugin<FirebaseMessagingPlugin>('FirebaseMessaging');
  return messaging;
}

let channelReady: Promise<void> | undefined;

/** Reads the token, making sure Android has the channel before anything can arrive on it. */
async function readToken(): Promise<string | null> {
  if (shellPlatform() === 'android') {
    channelReady ??= fcm()
      .createChannel({
        id: PUSH_CHANNEL,
        name: t('push.channel'),
        description: t('push.channelNote'),
        importance: PUSH_IMPORTANCE,
      })
      .catch((cause: unknown) => {
        channelReady = undefined;
        throw cause;
      });
    await channelReady;
  }
  const { token } = await fcm().getToken();
  return token === '' ? null : token;
}

const push: Push = {
  available: true,
  async token() {
    try {
      // Android 13+ and iOS share this permission with the daily reminder,
      // so a reminder that was allowed means this is allowed too.
      const { receive } = await fcm().checkPermissions();
      if (receive !== 'granted') return null;
      return await readToken();
    } catch (cause) {
      // No Google services, a blocked network or Firebase not configured:
      // the phone simply has no server notifications, and the local reminder
      // still works.
      console.error('push token unavailable', cause);
      return null;
    }
  },
  async enable() {
    try {
      let { receive } = await fcm().checkPermissions();
      if (receive === 'prompt' || receive === 'prompt-with-rationale') {
        receive = (await fcm().requestPermissions()).receive;
      }
      if (receive !== 'granted') return null;
      return await readToken();
    } catch (cause) {
      console.error('push could not be enabled', cause);
      return null;
    }
  },
  onToken(listener) {
    const handle = fcm().addListener('tokenReceived', ({ token }) => {
      if (token !== '') listener(token);
    });
    return () => {
      quietly(handle.then((h) => h.remove()));
    };
  },
  onTap(handler) {
    const handle = fcm().addListener('notificationActionPerformed', ({ notification }) => {
      handler(pushPath(notification.data));
    });
    // Android hands a push that arrives while the app is open to the app
    // instead of showing it, so an operator's test, a gift or an
    // announcement would vanish exactly when somebody is looking. Show it
    // ourselves, as a local notification on the same channel carrying the
    // same link; its tap goes through the local listener in lifecycle.ready.
    // iOS shows it already (presentationOptions in the shell's config).
    const shown =
      shellPlatform() === 'android'
        ? fcm().addListener('notificationReceived', ({ notification }) => {
            quietly(
              import('@capacitor/local-notifications').then(({ LocalNotifications }) =>
                LocalNotifications.schedule({
                  notifications: [
                    {
                      id: nextForegroundId(),
                      title: notification.title ?? '',
                      body: notification.body ?? '',
                      channelId: PUSH_CHANNEL,
                      extra: { link: pushPath(notification.data) },
                      // Shown now, with no alarm, but the plugin defaults
                      // to "exact" and, without the exact-alarm permission,
                      // sends the user to Android's Alarms & reminders
                      // settings instead of showing anything.
                      isExactNotification: false,
                    },
                  ],
                }),
              ),
            );
          })
        : undefined;
    return () => {
      quietly(handle.then((h) => h.remove()));
      if (shown) quietly(shown.then((h) => h.remove()));
    };
  },
  onReceive(listener) {
    const handle = fcm().addListener('notificationReceived', () => {
      listener();
    });
    return () => {
      quietly(handle.then((h) => h.remove()));
    };
  },
};

/**
 * Ids for pushes shown while the app is open, kept clear of REMINDER_IDS so
 * re-planning the reminders never cancels one. A small rotating block: an
 * id reused after a hundred notifications replaces one long since read.
 */
const FOREGROUND_IDS = { first: 900, count: 100 } as const;
let foregroundTurn = 0;
function nextForegroundId(): number {
  foregroundTurn = (foregroundTurn + 1) % FOREGROUND_IDS.count;
  return FOREGROUND_IDS.first + foregroundTurn;
}

/** Keeps the status bar readable when the app switches theme. */
function followTheme(): void {
  const apply = (): void => {
    const dark = document.documentElement.dataset.theme === 'dark';
    quietly(
      import('@capacitor/status-bar').then(({ StatusBar, Style }) =>
        StatusBar.setStyle({ style: dark ? Style.Dark : Style.Light }),
      ),
    );
  };
  apply();
  new MutationObserver(apply).observe(document.documentElement, {
    attributes: true,
    attributeFilter: ['data-theme'],
  });
}

const lifecycle: Lifecycle = {
  ready() {
    quietly(import('@capacitor/splash-screen').then(({ SplashScreen }) => SplashScreen.hide()));
    quietly(
      import('@capacitor/network').then(async ({ Network }) => {
        online = (await Network.getStatus()).connected;
        await Network.addListener('networkStatusChange', (status) => {
          online = status.connected;
          for (const listener of networkListeners) listener(online);
        });
      }),
    );
    quietly(
      import('@capacitor/app').then(({ App }) =>
        App.addListener('backButton', () => {
          const action = backButtonAction(window.location.hash, isFirstEntry(window.history.state));
          if (action === 'exit') void App.exitApp();
          else if (action === 'back') window.history.back();
          else window.location.replace(`#${action.up}`);
        }),
      ),
    );
    /*
     * WKWebView puts a form assistant above the keyboard: two chevrons for
     * stepping between fields and a Done tick. It is Safari's furniture,
     * not ours — it appears over every sheet in the app, it steps through
     * fields in an order nothing here chose, and it is the one thing on
     * screen that says this is a web view rather than an app.
     *
     * The keyboard is dismissed by the app's own controls and by tapping
     * away from the field, so nothing is lost with it. Android has no such
     * bar and the call is not made there.
     */
    if (shellPlatform() === 'ios') {
      quietly(
        import('@capacitor/keyboard').then(({ Keyboard }) =>
          Keyboard.setAccessoryBarVisible({ isVisible: false }),
        ),
      );
    }
    // A link to the web app (a shared notebook, an e-mailed confirmation)
    // opens here when the phone sends it to the app: at launch, or while
    // running. Only the paths in appLink.ts are taken; anything else is
    // left alone rather than guessed at.
    quietly(
      import('@capacitor/app').then(async ({ App }) => {
        const host = import.meta.env.VITE_APP_LINK_HOST ?? '';
        const open = (url: string | undefined): void => {
          const path = url === undefined ? null : appLinkPath(url, host);
          if (path !== null) window.location.hash = `#${path}`;
        };
        await App.addListener('appUrlOpen', ({ url }) => {
          open(url);
        });
        open((await App.getLaunchUrl())?.url);
      }),
    );
    quietly(
      import('@capacitor/local-notifications').then(({ LocalNotifications }) =>
        LocalNotifications.addListener('localNotificationActionPerformed', ({ notification }) => {
          // A reminder carries no link and is about today's practice, so it
          // lands on Today; a push shown while the app was open carries its
          // own link (see push.onTap), checked like any other.
          window.location.hash = `#${pushPath(notification.extra)}`;
        }),
      ),
    );
    followTheme();
  },
  onResume(listener) {
    let removed = false;
    const handle = import('@capacitor/app').then(({ App }) =>
      App.addListener('appStateChange', ({ isActive }) => {
        if (isActive && !removed) listener();
      }),
    );
    return () => {
      removed = true;
      quietly(handle.then((h) => h.remove()));
    };
  },
};

let googleReady: Promise<void> | undefined;

/**
 * Google Sign-In through the platform SDK. The ID token it returns names
 * the web client id as audience, which is what the API verifies; a shell
 * never has a Google code to send.
 */
const signIn: NativeSignIn = {
  available: true,
  async googleIdToken(webClientId) {
    const { SocialLogin } = await import('@capgo/capacitor-social-login');
    // iOS signs in through its own OAuth client but asks for a token
    // addressed to the web client, which is the audience the API verifies.
    const iOSClientId = import.meta.env.VITE_GOOGLE_IOS_CLIENT_ID;
    googleReady ??= SocialLogin.initialize({
      google: iOSClientId ? { webClientId, iOSClientId, iOSServerClientId: webClientId } : { webClientId },
    });
    await googleReady;
    // No explicit scopes: email, profile and openid are the plugin's defaults,
    // and naming any scope switches it to the authorization flow, which
    // rejects unless MainActivity implements its result-handling interface.
    const outcome = await SocialLogin.login({ provider: 'google', options: {} });
    const token = 'idToken' in outcome.result ? outcome.result.idToken : null;
    if (!token) throw new Error('Google Sign-In returned no id token');
    return token;
  },
};

/** The shells receive server notifications through `push`; Web Push is the browser's. */
const webPush: WebPush = {
  support: () => Promise.resolve('unavailable'),
  subscription: () => Promise.resolve(null),
  subscribe: () => Promise.resolve({ status: 'failed' }),
  unsubscribe: () => Promise.resolve(),
};

export const platform: Platform = {
  env: readEnv(),
  tts,
  speech,
  haptics,
  secure,
  prefs,
  share,
  network,
  reminders,
  push,
  webPush,
  lifecycle,
  signIn,
};
