/**
 * Whether this device has been shown the introduction. It lives in the
 * small preferences store rather than IndexedDB because the decision is
 * made before anything else loads, and because signing out clears the
 * database but must not bring the introduction back: whoever signs out has
 * already seen the app.
 */
import { platform } from '@/lib/platform/index.js';

const KEY = 'wb.intro';

export function introSeen(): boolean {
  return platform.prefs.get(KEY) === '1';
}

export function markIntroSeen(): void {
  platform.prefs.set(KEY, '1');
}
