import { Button } from '@/components/ui/Button.js';
import { t } from '@/i18n/index.js';
import styles from './Crashed.module.css';

/**
 * What the whole app shows when a render throws. Local data is untouched,
 * so a reload is the honest fix; the error has already been reported.
 */
export function Crashed(): React.JSX.Element {
  return (
    <main className={styles.screen} role="alert">
      <h1 className={styles.title}>{t('error.crashTitle')}</h1>
      <p className={styles.body}>{t('error.crashBody')}</p>
      <Button
        size="large"
        onClick={() => {
          window.location.reload();
        }}
      >
        {t('error.reload')}
      </Button>
    </main>
  );
}
