/**
 * Where a tapped notification may take the app. The server puts an in-app
 * path in `data.link`; anything else — a full address, a protocol-relative
 * `//host`, a backslash a web view might read as a slash, or nothing at all —
 * lands on Today, because a notification must never be a way to send
 * somebody out of the app or to a route that does not exist.
 */
export const PUSH_FALLBACK_PATH = '/';

export function pushPath(data: unknown): string {
  if (typeof data !== 'object' || data === null) return PUSH_FALLBACK_PATH;
  const link = (data as { link?: unknown }).link;
  if (typeof link !== 'string') return PUSH_FALLBACK_PATH;
  if (!link.startsWith('/') || link.startsWith('//') || link.includes('\\')) return PUSH_FALLBACK_PATH;
  // Control characters and spaces have no place in a route.
  if ([...link].some((char) => char.charCodeAt(0) <= 0x20 || char.charCodeAt(0) === 0x7f)) {
    return PUSH_FALLBACK_PATH;
  }
  return link;
}
