import { useRegisterSW } from 'virtual:pwa-register/react';
import { Button } from '@/components/ui/Button.js';
import { t } from '@/i18n/index.js';
import styles from './UpdateToast.module.css';

/**
 * A new build is ready. The prompt never interrupts practice: it waits at
 * the bottom until the user chooses to reload.
 */
export function UpdateToast(): React.JSX.Element | null {
  const {
    needRefresh: [needRefresh],
    updateServiceWorker,
  } = useRegisterSW({ immediate: true });

  if (!needRefresh) return null;

  return (
    <div className={styles.toast} role="status">
      <span className={styles.text}>{t('settings.updateAvailable')}</span>
      <Button
        size="small"
        onClick={() => {
          void updateServiceWorker(true);
        }}
      >
        {t('settings.reload')}
      </Button>
    </div>
  );
}
