import { createBrowserRouter, createHashRouter, type RouteObject } from 'react-router-dom';
import { App } from './App.js';
import { AuthGate, SignedOutOnly } from './AuthGate.js';
import { Placeholder } from './routes/Placeholder.js';
import { Spinner } from '@/components/ui/Spinner.js';
import { SignIn } from '@/features/auth/SignIn.js';
import { Intro } from '@/features/intro/Intro.js';
import { GoogleCallback } from '@/features/auth/GoogleCallback.js';
import { ForgotPassword } from '@/features/auth/ForgotPassword.js';
import { ResetPassword } from '@/features/auth/ResetPassword.js';
import { VerifyEmail } from '@/features/auth/VerifyEmail.js';
import { Unsubscribe } from '@/features/auth/Unsubscribe.js';
import { ConnectExtension } from '@/features/auth/ConnectExtension.js';
import { ConnectDesktop } from '@/features/auth/ConnectDesktop.js';
import { ConnectAssistant } from '@/features/connect/ConnectAssistant.js';
import { platform } from '@/lib/platform/index.js';
import { t } from '@/i18n/index.js';

/**
 * Each screen is its own chunk, fetched the first time it is opened and kept
 * by the service worker afterwards. Sign-in stays in the main bundle: it is
 * the first thing a new visitor sees and should not wait on a second request.
 */
async function screen<K extends string>(
  loading: Promise<Record<K, React.ComponentType>>,
  name: K,
): Promise<{ Component: React.ComponentType }> {
  const module = await loading;
  return { Component: module[name] };
}

const routes: RouteObject[] = [
  /*
   * Two known accounts to look at while designing, at /preview.
   *
   * Outside the gate on purpose: it has to work before there is an account
   * to gate on, and the gate sends anybody without a notebook to
   * onboarding, which is exactly the state this is for setting up.
   *
   * The condition is a build-time constant, so a release drops both this
   * entry and the module it names; the sample words never reach a bundle
   * anybody downloads.
   */
  ...(import.meta.env.DEV
    ? [{ path: '/preview', lazy: () => screen(import('@/features/dev/Preview.js'), 'Preview') }]
    : []),
  // Sign-in sits outside the gate; everything else requires a session.
  {
    path: '/auth',
    element: (
      <SignedOutOnly>
        <SignIn />
      </SignedOutOnly>
    ),
  },
  // The first thing a stranger sees, once per device; skipped by anyone who has signed in before.
  {
    path: '/intro',
    element: (
      <SignedOutOnly>
        <Intro />
      </SignedOutOnly>
    ),
  },
  { path: '/auth/google/callback', element: <GoogleCallback /> },
  // The browser extension opens this to be connected; it needs a signed-in user but no tab bar.
  {
    path: '/connect-extension',
    element: (
      <AuthGate>
        <ConnectExtension />
      </AuthGate>
    ),
  },
  // The desktop app opens this in the system browser to be connected (RFC 8252):
  // gated like the extension's page, no tab bar, and it only ever sends the
  // browser back to the app's own loopback address.
  {
    path: '/connect-desktop',
    element: (
      <AuthGate>
        <ConnectDesktop />
      </AuthGate>
    ),
  },
  // ChatGPT or Claude sends the learner here to approve a connection. Gated
  // like the extension's page, with no tab bar; the gate brings a signed-out
  // visitor back here with the request id once they have signed in.
  {
    path: '/connect/ai',
    element: (
      <AuthGate>
        <ConnectAssistant />
      </AuthGate>
    ),
  },
  // E-mailed links land here, signed in or not.
  { path: '/verify', element: <VerifyEmail /> },
  { path: '/forgot', element: <ForgotPassword /> },
  { path: '/reset-password', element: <ResetPassword /> },
  // The way out of the product news, from the foot of every one of them. It
  // asks for no session: somebody who cannot sign in must still be able to
  // stop the e-mails.
  { path: '/unsubscribe', element: <Unsubscribe /> },
  // A shared notebook. The one screen in Lexpad that needs no account at
  // all: it is how somebody's words reach a friend who has never heard of
  // the app, so a gate here would defeat the whole point of a link.
  {
    path: '/s/:shareId',
    lazy: () => screen(import('@/features/share/SharedNotebook.js'), 'SharedNotebook'),
  },
  // A promotion code, typed or arrived at by a link. Outside the gate for
  // the same reason a shared notebook is: an influencer's link is followed
  // by people who have never heard of Lexpad, and a page that cannot say
  // what it is offering until you sign in is a page nobody finishes.
  {
    path: '/promo/:code',
    lazy: () => screen(import('@/features/promo/Promo.js'), 'Promo'),
  },
  {
    path: '/promo',
    lazy: () => screen(import('@/features/promo/Promo.js'), 'Promo'),
  },
  {
    path: '/',
    element: (
      <AuthGate>
        <App />
      </AuthGate>
    ),
    // Shown only on a hard load of a lazy screen, before its code arrives;
    // in-app navigation keeps the current screen until the next is ready.
    HydrateFallback: Spinner,
    children: [
      { index: true, lazy: () => screen(import('@/features/today/Today.js'), 'Today') },
      // The notebook and a word: two screens on a phone, side by side on an
      // expanded window (features/notebook/NotebookLayout.tsx).
      {
        lazy: () => screen(import('@/features/notebook/NotebookLayout.js'), 'NotebookLayout'),
        children: [
          { path: 'notebook', lazy: () => screen(import('@/features/notebook/Notebook.js'), 'Notebook') },
          {
            path: 'words/:wordId',
            lazy: () => screen(import('@/features/word/WordDetail.js'), 'WordDetail'),
          },
        ],
      },
      { path: 'progress', lazy: () => screen(import('@/features/progress/Progress.js'), 'Progress') },
      // Settings and the pages it opens (/settings/account, /settings/practice…).
      {
        path: 'settings/*',
        lazy: () => screen(import('@/features/settings/SettingsRoutes.js'), 'SettingsRoutes'),
      },
      { path: 'session', lazy: () => screen(import('@/features/session/Session.js'), 'Session') },
      { path: 'ai', lazy: () => screen(import('@/features/ai/AiCards.js'), 'AiCards') },
      { path: 'assistant', lazy: () => screen(import('@/features/assistant/Assistant.js'), 'Assistant') },
      { path: 'read', lazy: () => screen(import('@/features/read/Read.js'), 'Read') },
      { path: 'welcome', lazy: () => screen(import('@/features/onboarding/Onboarding.js'), 'Onboarding') },
      { path: 'decks', lazy: () => screen(import('@/features/decks/Decks.js'), 'Decks') },
      // The card gallery draws made-up words for whoever is building the
      // app. It was reachable in production until 2026-09-30; nothing a
      // learner can open may show vocabulary that is not theirs.
      ...(import.meta.env.DEV
        ? [{ path: 'gallery', lazy: () => screen(import('@/features/gallery/Gallery.js'), 'Gallery') }]
        : []),
      { path: '*', element: <Placeholder title={t('notFound.title')} note={t('notFound.body')} /> },
    ],
  },
];

/**
 * A hash router inside the native shells, where the web layer is loaded
 * from the file system and history paths do not resolve; a normal browser
 * router on the web, so URLs are shareable.
 */
export function createRouter(): ReturnType<typeof createBrowserRouter> {
  return platform.env.embedded ? createHashRouter(routes) : createBrowserRouter(routes);
}
