import { Screen } from '@/components/layout/Screen.js';

/**
 * A screen that is routed but not built yet. Each one is replaced by the
 * real screen in its own commit, so the shell is navigable throughout.
 */
export function Placeholder({ title, note }: { title: string; note: string }): React.JSX.Element {
  return (
    <Screen title={title}>
      <p style={{ color: 'var(--dim)' }}>{note}</p>
    </Screen>
  );
}
