import { TabBar } from '@/components/layout/TabBar.js';
import { Sidebar } from '@/features/sidebar/Sidebar.js';
import { atLeast, useWindowClass } from '@/lib/windowClass.js';

/**
 * The app's navigation for the window it is in: the floating bottom bar on
 * a phone, the sidebar at the side on anything wider (lib/windowClass.ts),
 * folded into a rail or open (lib/sidebar.ts). It lives with the frame
 * rather than in components because the sidebar reads the notebook, the
 * account and Today's numbers.
 * One or the other is mounted, never both, so a screen reader finds one
 * "Main" navigation and the bar's scroll listener is not running behind a
 * rail.
 */
export function Navigation(): React.JSX.Element {
  const size = useWindowClass();
  return atLeast(size, 'medium') ? <Sidebar /> : <TabBar />;
}
