/**
 * Where the consent screen may send the browser after a decision.
 *
 * The server builds the address from the redirect it registered for the
 * client and checked against its own allow-list; this is the same list,
 * checked again here as defence in depth, so a server bug or a tampered
 * response can never turn the consent screen into an open redirect. It lives
 * in code rather than in data on purpose: it is a security boundary, and a
 * value fetched at run time could be changed by the very thing it guards
 * against. Keep it in step with the allow-list in the API (`lexpad_back`).
 */
const ASSISTANT_ORIGINS: ReadonlySet<string> = new Set([
  'https://chatgpt.com',
  'https://claude.ai',
  'https://claude.com',
]);

/** Desktop and command-line assistants receive the code on this machine (RFC 8252). */
const LOOPBACK_HOSTS: ReadonlySet<string> = new Set(['localhost', '127.0.0.1']);

/**
 * The parsed address when it is safe to navigate to, otherwise undefined.
 * `expectedHost` is the verified host the screen showed the learner; the
 * answer must go there and nowhere else.
 */
export function assistantRedirect(raw: unknown, expectedHost: string): URL | undefined {
  if (typeof raw !== 'string' || raw.length === 0) return undefined;
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return undefined;
  }
  if (url.username !== '' || url.password !== '' || url.hash !== '') return undefined;
  const loopback = url.protocol === 'http:' && LOOPBACK_HOSTS.has(url.hostname);
  const assistant = url.protocol === 'https:' && url.port === '' && ASSISTANT_ORIGINS.has(url.origin);
  if (!loopback && !assistant) return undefined;
  if (url.host !== expectedHost && url.hostname !== expectedHost) return undefined;
  return url;
}
