/**
 * Who is signed in, and how the app got there.
 *
 * The store is the single answer to "should we show the app, sign-in, or a
 * spinner", so no screen has to work it out for itself.
 */
import { create } from 'zustand';
import { ApiError, isApiError } from '@/api/errors.js';
import type { ApiUser } from '@/api/types.js';
import { auth as authApi, devices as devicesApi, me as meApi } from '@/api/endpoints.js';
import { describeDevice } from '@/lib/deviceName.js';
import {
  clearSession,
  hasSession,
  noteDesktopSession,
  onSessionEnded,
  restoreSession,
} from '@/api/client.js';
import { clearLocalData, getMeta, setMeta } from '@/db/schema.js';
import { outboxSize } from '@/db/repo.js';
import { bootstrap, isBootstrapped, pushAll, syncOnce } from '@/sync/worker.js';
import { platform } from '@/lib/platform/index.js';
import { localTimeZone } from '@/lib/format.js';
import { syncReminder } from '@/sync/reminder.js';
import { t } from '@/i18n/index.js';

/** The signed-in account, as the app needs it. */
export interface CurrentUser {
  id: string;
  email: string;
  displayName: string;
  timezone: string;
  locale: string;
  /** Whether the address was confirmed through the e-mailed link. */
  emailVerified: boolean;
  /** Consent to product news by e-mail. */
  marketingOptIn: boolean;
  /** How the account signs in: password, google, apple. Known after the profile is read. */
  providers: readonly string[];
}

/** The account as the API describes it, in the shape the app keeps. */
export function toCurrentUser(u: ApiUser): CurrentUser {
  return {
    id: u.id,
    email: u.email,
    displayName: u.displayName,
    timezone: u.timezone,
    locale: u.locale,
    emailVerified: u.emailVerified === true,
    marketingOptIn: u.marketingOptIn === true,
    providers: u.providers ?? [],
  };
}

/** Where the boot sequence has got to. */
export type AuthStatus =
  /** Still deciding: a stored session may exist. */
  | 'checking'
  /** No session; show sign-in. */
  | 'signedOut'
  /** Signed in and the local database is ready. */
  | 'ready';

interface AuthState {
  status: AuthStatus;
  user: CurrentUser | null;
  /** True for a brand-new account, which sends the user to onboarding. */
  isNewUser: boolean;
  error: string | null;
  busy: boolean;

  boot: () => Promise<void>;
  signIn: (email: string, password: string) => Promise<void>;
  signUp: (email: string, password: string, marketingOptIn: boolean) => Promise<void>;
  /** Re-reads the account from the API, so a confirmation done elsewhere shows here. */
  refreshUser: () => Promise<void>;
  /** Replaces the account after the API changed it, for example a confirmed address. */
  setUser: (user: CurrentUser) => Promise<void>;
  /** The web hands over Google's redirect code; a native shell the SDK's ID token. */
  signInWithGoogle: (credential: { code: string } | { idToken: string }) => Promise<void>;
  signInWithApple: (idToken: string, displayName?: string) => Promise<void>;
  /**
   * Inside the desktop app: connects it in the system browser (where the
   * learner signs in however they like) and then opens the account here.
   */
  connectDesktop: () => Promise<void>;
  /** Stops waiting for the browser. */
  cancelDesktopConnect: () => Promise<void>;
  /** Signs out unless changes are still waiting to reach the server. */
  signOut: () => Promise<{ outcome: 'done' | 'pending'; pending: number }>;
  /** Asks the server to erase the account, then clears this device. */
  deleteAccount: () => Promise<void>;
  clearError: () => void;
}

function deviceInfo(): {
  platform: 'web' | 'ios' | 'android' | 'desktop';
  deviceId: string;
  deviceName: string;
  appVersion: string;
} {
  return {
    platform: platform.env.platform,
    deviceId: platform.env.deviceId,
    deviceName: describeDevice(),
    appVersion: platform.env.appVersion,
  };
}

/**
 * How long registration waits for a push token before going without one.
 * Firebase can take a while on a cold start and never answers where Google
 * is blocked; the device list must not wait on it. A token that turns up
 * later is sent then. A constant because it is about the network, not a
 * product decision anyone would tune.
 */
export const PUSH_TOKEN_WAIT_MS = 10_000;

/** The token the server last heard from this run, so a repeat is not sent twice. */
let sentToken: string | null = null;

/** Resolves with the value, or with undefined once `ms` has passed. */
function within<T>(work: Promise<T>, ms: number): Promise<T | undefined> {
  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      resolve(undefined);
    }, ms);
    void work.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      () => {
        clearTimeout(timer);
        resolve(undefined);
      },
    );
  });
}

/**
 * Tells the server this install exists: what it is, where it is, which build
 * it runs and, inside the shells, the push token server notifications go to.
 * Called on every start once signed in, so the account's device list stays
 * current, and again whenever the token changes. `token` is a token already
 * in hand; without one the platform is asked, which never prompts for
 * permission. Silent on failure; nothing the learner does depends on it.
 */
export async function registerDevice(token?: string): Promise<void> {
  const pending = token === undefined ? platform.push.token() : Promise.resolve(token);
  const pushToken = await within(pending, PUSH_TOKEN_WAIT_MS);
  if (pushToken === undefined && token === undefined) {
    // Too slow this time: register now, and again if the token does arrive.
    void pending.then((late) => (late === null ? undefined : registerDevice(late))).catch(() => undefined);
  }
  // A browser that has subscribed sends its subscription every time: a
  // registration without one tells the server this browser takes no pop-ups.
  const webPushSubscription = pushToken ? null : await platform.webPush.subscription().catch(() => null);
  try {
    const locale = typeof navigator === 'undefined' ? '' : navigator.language;
    await devicesApi.register({
      ...deviceInfo(),
      timezone: localTimeZone(),
      ...(locale === '' ? {} : { locale }),
      ...(pushToken ? { pushProvider: 'fcm' as const, pushToken } : {}),
      ...(webPushSubscription ? { pushProvider: 'webpush' as const, webPushSubscription } : {}),
    });
    if (pushToken) sentToken = pushToken;
    // Whoever can reach this install sends the come-back nudges; re-plan the
    // local reminders when that changes (see MetaShape.pushReceives). In the
    // background: registering does not wait on it.
    void notePushReceives(Boolean(pushToken));
  } catch {
    // Offline or a server hiccup: the next start tries again.
  }
}

async function notePushReceives(receives: boolean): Promise<void> {
  try {
    if ((await getMeta('pushReceives')) === receives) return;
    await setMeta('pushReceives', receives);
    await syncReminder();
  } catch {
    // The next start notes it again.
  }
}

/** Registers again when Firebase hands this install a token the server has not seen. */
export function registerPushToken(token: string): Promise<void> {
  if (token === sentToken) return Promise.resolve();
  return registerDevice(token);
}

/**
 * Asks for notification permission at a moment the learner chose (turning a
 * reminder or product news on) and sends the token if one comes back. Never
 * called at start-up, so nobody meets a dialog before they have seen the app.
 */
export async function enablePush(): Promise<void> {
  if (!platform.push.available) return;
  const token = await platform.push.enable();
  if (token !== null) await registerPushToken(token);
}

/**
 * Turns notifications on in this browser: asks for permission (the learner
 * just flipped the switch), subscribes with the server's VAPID key and
 * registers the subscription. Resolves with what happened, so Settings can
 * say why it did not work.
 */
export async function turnOnBrowserPush(applicationServerKey: string): Promise<'on' | 'denied' | 'failed'> {
  const outcome = await platform.webPush.subscribe(applicationServerKey);
  if (outcome.status !== 'subscribed') return outcome.status;
  try {
    await devicesApi.register({
      ...deviceInfo(),
      timezone: localTimeZone(),
      pushProvider: 'webpush',
      webPushSubscription: outcome.subscription,
    });
    return 'on';
  } catch {
    // Subscribed but the server never heard: nothing would arrive, so the
    // switch must not claim otherwise. Drop it and let the learner retry.
    await platform.webPush.unsubscribe();
    return 'failed';
  }
}

/** Turns notifications off in this browser, and tells the server so. */
export async function turnOffBrowserPush(): Promise<void> {
  await platform.webPush.unsubscribe();
  // Registering without a subscription is how the server forgets it; the
  // push service also answers 410 for an unsubscribed endpoint, so a missed
  // call here costs nothing but one failed send.
  await registerDevice();
}

/** Turns an API failure into a sentence the sign-in form can show. */
/**
 * What a failed provider sign-in says. A 401 there means Google or Apple
 * would not vouch for the code, not that a password was wrong, so the
 * generic credentials message would mislead.
 */
function providerMessageFor(provider: string, error: unknown): string {
  if (isApiError(error, 'offline')) return t('error.offline');
  return t('auth.providerFailed', { provider });
}

function messageFor(error: unknown): string {
  if (isApiError(error, 'offline')) return t('error.offline');
  if (error instanceof ApiError) {
    switch (error.code) {
      case 'invalid_credentials':
        return t('auth.invalid');
      case 'email_taken':
        return t('auth.emailTaken');
      case 'weak_password':
        return t('auth.passwordShort');
      default:
        return error.kind === 'unauthenticated' ? t('auth.invalid') : error.message;
    }
  }
  return t('error.generic');
}

/** Stores the account locally so the app can render before the next sync. */
/**
 * Makes the local database belong to this account.
 *
 * The same person signing back in keeps everything, including edits queued
 * while the session was out: those are pushed, then the change log is
 * pulled. Anyone else starts from the server's snapshot, with whatever the
 * previous account left behind wiped first, so a queued edit can never land
 * in the wrong account.
 */
async function adoptAccount(user: CurrentUser): Promise<void> {
  const previous = await getMeta('user');
  if (previous?.id === user.id && (await isBootstrapped())) {
    await setMeta('user', user);
    await syncOnce();
    return;
  }
  await clearLocalData();
  // The snapshot writes the account itself; recording it only afterwards
  // means a failed bootstrap leaves nothing that looks like a finished setup.
  await bootstrap();
  await setMeta('user', user);
}

export const useAuth = create<AuthState>((set, get) => ({
  status: 'checking',
  user: null,
  isNewUser: false,
  error: null,
  busy: false,

  clearError() {
    set({ error: null });
  },

  /**
   * Decides what to show on launch. A local database that is already filled
   * wins: the app renders immediately from it, and the session is refreshed
   * in the background. Only an empty database has to wait for the network.
   */
  async boot() {
    const storedUser = await getMeta('user');
    // A stored account whose database was filled at least once renders at
    // once. One whose setup was cut short, say a snapshot that never
    // arrived, must not: an empty database would read as "no notebooks yet"
    // and send an existing account through onboarding, which creates a
    // second, empty notebook.
    if (storedUser && (await isBootstrapped())) {
      // A row from before the confirmation flag existed counts as confirmed
      // until the profile refresh says otherwise, so nobody is nagged offline.
      set({
        status: 'ready',
        user: {
          ...storedUser,
          emailVerified: storedUser.emailVerified ?? true,
          marketingOptIn: storedUser.marketingOptIn ?? false,
          providers: storedUser.providers ?? [],
        },
      });
      // Refresh the token quietly, then the profile; a failure will surface on the next call.
      void restoreSession().then((ok) => (ok ? get().refreshUser() : undefined));
      return;
    }

    const restored = await restoreSession();
    if (!restored) {
      set({ status: 'signedOut', user: null });
      return;
    }
    try {
      const profile = await meApi.get();
      const user = toCurrentUser(profile);
      await adoptAccount(user);
      set({ status: 'ready', user });
    } catch {
      clearSession();
      set({ status: 'signedOut', user: null });
    }
  },

  async refreshUser() {
    try {
      await get().setUser(toCurrentUser(await meApi.get()));
    } catch {
      // Offline or signed out: the stored account stands until the next attempt.
    }
  },

  async setUser(user) {
    await setMeta('user', user);
    set({ user });
  },

  async signIn(email, password) {
    set({ busy: true, error: null });
    try {
      const session = await authApi.login({ email, password, device: deviceInfo() });
      const user = toCurrentUser(session.user);
      await adoptAccount(user);
      set({ status: 'ready', user, isNewUser: false, busy: false });
    } catch (error) {
      set({ busy: false, error: messageFor(error) });
    }
  },

  async signUp(email, password, marketingOptIn) {
    set({ busy: true, error: null });
    try {
      const session = await authApi.register({
        email,
        password,
        timezone: localTimeZone(),
        marketingOptIn,
        device: deviceInfo(),
      });
      const user = toCurrentUser(session.user);
      await adoptAccount(user);
      set({ status: 'ready', user, isNewUser: true, busy: false });
    } catch (error) {
      set({ busy: false, error: messageFor(error) });
    }
  },

  async signInWithGoogle(credential) {
    set({ busy: true, error: null });
    try {
      const session = await authApi.google({ ...credential, device: deviceInfo() });
      const user = toCurrentUser(session.user);
      await adoptAccount(user);
      set({ status: 'ready', user, isNewUser: session.isNewUser === true, busy: false });
    } catch (error) {
      set({ busy: false, error: providerMessageFor('Google', error) });
    }
  },

  async signInWithApple(idToken, displayName) {
    set({ busy: true, error: null });
    try {
      const session = await authApi.apple({
        idToken,
        ...(displayName === undefined ? {} : { displayName }),
        device: deviceInfo(),
      });
      const user = toCurrentUser(session.user);
      await adoptAccount(user);
      set({ status: 'ready', user, isNewUser: session.isNewUser === true, busy: false });
    } catch (error) {
      set({ busy: false, error: providerMessageFor('Apple', error) });
    }
  },

  async connectDesktop() {
    const host = platform.desktop;
    if (host === undefined) return;
    set({ busy: true, error: null });
    try {
      await host.connect();
    } catch (cause) {
      const word = cause instanceof Error ? cause.message : 'error';
      // Cancelling is the learner's own choice and needs no message.
      set({ busy: false, error: word === 'cancelled' ? null : desktopMessageFor(word) });
      return;
    }
    noteDesktopSession();
    try {
      const user = toCurrentUser(await meApi.get());
      await adoptAccount(user);
      set({ status: 'ready', user, isNewUser: false, busy: false });
    } catch (error) {
      set({ busy: false, error: messageFor(error) });
    }
  },

  async cancelDesktopConnect() {
    await platform.desktop?.cancelConnect().catch(() => undefined);
  },

  /**
   * Signs out and wipes the local database. Anything still queued is lost,
   * which is the honest behaviour: the next person to use this browser must
   * not inherit someone else's words.
   */
  async signOut() {
    set({ busy: true });
    // Signing out wipes the local database, and a queued change exists
    // nowhere else. Send what is waiting first, and refuse while anything
    // remains, rather than lose it.
    try {
      if (platform.network.online) await pushAll();
    } catch {
      // A failed push leaves the items queued; the count below decides.
    }
    const pending = await outboxSize();
    if (pending > 0) {
      set({ busy: false });
      return { outcome: 'pending', pending };
    }
    if (hasSession()) {
      // The phone stops receiving this account's notifications, so a device
      // handed to somebody else does not carry on with the last owner's.
      // Before the logout, which ends the session this call needs.
      try {
        await devicesApi.unregister(platform.env.deviceId);
      } catch {
        // Best effort: the server also drops a token Firebase reports dead.
      }
      try {
        // The desktop app's core holds the session: it revokes it and
        // forgets it, which signs its add-a-word card out with it.
        if (platform.desktop !== undefined) await platform.desktop.disconnect();
        else await authApi.logout();
      } catch {
        // Losing the round trip does not stop us clearing local state.
      }
    }
    await leaveDevice();
    set({ status: 'signedOut', user: null, isNewUser: false, busy: false, error: null });
    return { outcome: 'done', pending: 0 };
  },

  async deleteAccount() {
    set({ busy: true });
    try {
      // The server revokes every session and starts the grace period; the
      // refresh cookie is cleared in the same response.
      await meApi.remove();
    } catch (cause) {
      set({ busy: false });
      throw cause;
    }
    // The server has ended every session; the desktop app's core forgets its own.
    await platform.desktop?.disconnect().catch(() => undefined);
    await leaveDevice();
    set({ status: 'signedOut', user: null, isNewUser: false, busy: false, error: null });
  },
}));

/**
 * Forgets the account on this device: the session, the database and the
 * daily reminder, which would otherwise keep nudging someone who left.
 */
async function leaveDevice(): Promise<void> {
  clearSession();
  sentToken = null;
  await platform.reminders.schedule(null).catch(() => undefined);
  // A browser shared with somebody else must not carry on with this
  // account's notifications, nor offer them to the next one as switched on.
  await platform.webPush.unsubscribe().catch(() => undefined);
  await clearLocalData();
}

/**
 * Sends the app back to sign-in when a refresh fails mid-session. Inside the
 * desktop app it also follows the core: signing out from the app's Settings
 * window shows sign-in here, and connecting there opens the account here.
 */
export function watchSessionEnd(): () => void {
  const stopEnded = onSessionEnded(() => {
    useAuth.setState({ status: 'signedOut', user: null });
  });
  const host = platform.desktop;
  const stopHost =
    host === undefined
      ? () => undefined
      : host.onSessionChange(() => {
          void restoreSession().then((signedIn) => {
            const { status, busy } = useAuth.getState();
            if (!signedIn && status === 'ready') useAuth.setState({ status: 'signedOut', user: null });
            // A connect this window started finishes on its own.
            else if (signedIn && status === 'signedOut' && !busy) void useAuth.getState().boot();
          });
        });
  return () => {
    stopEnded();
    stopHost();
  };
}

/** What a desktop connect that did not finish says. */
function desktopMessageFor(word: string): string {
  if (word === 'offline') return t('error.offline');
  if (word === 'timeout') return t('auth.desktopTimeout');
  return t('auth.desktopFailed');
}
