/**
 * Theme and palette. These two are the only settings that must be applied
 * before the first paint, so they live in localStorage (written by the
 * inline script in index.html) as well as in the user's server-side
 * settings. Everything else is data and lives in IndexedDB.
 */
import { create } from 'zustand';
import { platform } from './platform/index.js';

export type Theme = 'system' | 'dark' | 'light';
export type Palette = 'forest' | 'coral';

export const PALETTES: readonly Palette[] = ['forest', 'coral'];
export const THEMES: readonly Theme[] = ['system', 'dark', 'light'];

const THEME_KEY = 'wb.theme';
const PALETTE_KEY = 'wb.palette';

/** The colour the browser chrome should match, per resolved theme. */
const THEME_COLORS: Record<'dark' | 'light', string> = { dark: '#0c0d0f', light: '#f7f5f2' };

function isTheme(value: string | null): value is Theme {
  return value === 'system' || value === 'dark' || value === 'light';
}

function isPalette(value: string | null): value is Palette {
  return value === 'forest' || value === 'coral';
}

function prefersDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches;
}

/** Resolves `system` against the OS setting. */
export function resolveTheme(theme: Theme): 'dark' | 'light' {
  if (theme === 'system') return prefersDark() ? 'dark' : 'light';
  return theme;
}

/** Stamps the resolved theme and palette on the document root. */
function apply(theme: Theme, palette: Palette): void {
  const resolved = resolveTheme(theme);
  const root = document.documentElement;
  root.dataset.theme = resolved;
  root.dataset.palette = palette;
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', THEME_COLORS[resolved]);
}

interface ThemeState {
  theme: Theme;
  palette: Palette;
  setTheme: (theme: Theme) => void;
  setPalette: (palette: Palette) => void;
}

export const useTheme = create<ThemeState>((set, get) => ({
  theme: isTheme(platform.prefs.get(THEME_KEY)) ? (platform.prefs.get(THEME_KEY) as Theme) : 'system',
  palette: isPalette(platform.prefs.get(PALETTE_KEY))
    ? (platform.prefs.get(PALETTE_KEY) as Palette)
    : 'forest',
  setTheme(theme) {
    platform.prefs.set(THEME_KEY, theme);
    apply(theme, get().palette);
    set({ theme });
  },
  setPalette(palette) {
    platform.prefs.set(PALETTE_KEY, palette);
    apply(get().theme, palette);
    set({ palette });
  },
}));

/**
 * Applies the stored values and follows the OS while the theme is `system`.
 * Called once at boot; returns an unsubscribe for tests.
 */
export function startTheme(): () => void {
  const { theme, palette } = useTheme.getState();
  apply(theme, palette);
  const media = window.matchMedia('(prefers-color-scheme: dark)');
  const onChange = (): void => {
    const state = useTheme.getState();
    if (state.theme === 'system') apply(state.theme, state.palette);
  };
  media.addEventListener('change', onChange);
  return () => {
    media.removeEventListener('change', onChange);
  };
}
