import { pushPath, PUSH_FALLBACK_PATH } from './pushLink.js';

/**
 * The paths a link to the web app may open inside a shell (Android App
 * Links, iOS Universal Links). Keep it in step with the intent filter in
 * the Android shell's AndroidManifest.xml and the apple-app-site-association
 * file: a path missing there never reaches the app, a path missing here is
 * ignored by it.
 *
 * Deliberately absent: /connect/ai and /connect-extension (an assistant's
 * approval is bound to the browser that started it, by a cookie the app's
 * web view does not have) and /auth/* (Google's sign-in returns to the
 * browser that asked).
 */
export const APP_LINK_PREFIXES = [
  '/s/',
  '/verify',
  '/reset-password',
  '/forgot',
  '/promo',
  '/words/',
  '/notebook',
  '/progress',
  '/settings',
  '/decks',
  '/read',
] as const;

/**
 * The in-app path an opened link should show, or null when the link is not
 * one the app takes: another host, not https, or a path outside the list.
 * The bare address opens Today. The path then passes the same check a
 * notification's link does, so a link can never lead out of the app.
 */
export function appLinkPath(url: string, host: string): string | null {
  if (host === '') return null;
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  if (parsed.protocol !== 'https:' || parsed.hostname !== host || parsed.port !== '') return null;
  const path = parsed.pathname;
  const allowed =
    path === '/' ||
    APP_LINK_PREFIXES.some((prefix) =>
      prefix.endsWith('/')
        ? path.startsWith(prefix) && path.length > prefix.length
        : path === prefix || path.startsWith(`${prefix}/`),
    );
  if (!allowed) return null;
  const target = pushPath({ link: `${path}${parsed.search}` });
  return target === PUSH_FALLBACK_PATH && path !== '/' ? null : target;
}
