/**
 * The one word the introduction demonstrates with. The headword is English,
 * the most common target; its meaning follows the phone's language when we
 * have it, so a Persian phone sees a Persian meaning on the first screen.
 */
import { LANGUAGES, type LanguageCode } from '@lexpad/core';

export interface Sense {
  meaning: string;
  example: string;
}

export interface Sample {
  headword: string;
  pronunciation: string;
  pos: string;
  level: string;
  meaningLang: LanguageCode;
  /** The first sense is what the flashcard shows; the AI screen shows both. */
  meaning: string;
  example: string;
  senses: readonly Sense[];
  collocations: readonly string[];
}

