/** The phone's language when it is one we support; English otherwise. */
export function deviceLanguage(
  tag: string = typeof navigator === 'undefined' ? 'en' : navigator.language,
): LanguageCode {
  const primary = tag.split('-')[0]?.toLowerCase() ?? 'en';
  return (LANGUAGES as readonly string[]).includes(primary) ? (primary as LanguageCode) : 'en';
}

export function sampleFor(meaningLang: LanguageCode): Sample {
  const light = MEANINGS[meaningLang] ?? MEANINGS.en ?? '';
  const clever = CLEVER_MEANINGS[meaningLang] ?? CLEVER_MEANINGS.en ?? '';
  return {
    headword: 'bright',
    pronunciation: '/braɪt/',
    pos: 'adjective',
    level: 'B1',
    meaningLang,
    meaning: light,
    example: 'The room was bright and sunny.',
    senses: [
      { meaning: light, example: 'The room was bright and sunny.' },
      { meaning: clever, example: 'She is a bright student who learns fast.' },
    ],
    collocations: ['a bright idea', 'a bright future', 'bright colours'],
  };
}
