/**
 * Keeps the host's reminders in step with the synced setting and with what
 * the learner has done. Runs at boot, after a change in Settings, after every
 * pull and when a session ends, so the plan is rebuilt whenever the app is
 * used: a time chosen on another device takes effect here without a restart,
 * a finished session cancels tonight's streak nudge, and opening the app
 * pushes the come-back nudges another week away.
 *
 * Runs are serialised. Boot and the first pull land within the same second,
 * and a host can hold only one permission prompt at a time: the second
 * request would be answered "denied" while the first dialog was still open.
 */
import { activeToday, dayIndex, effectiveStreak, isDue, type Streak } from '@lexpad/core';
import { getActiveNotebook, listWords, loadSettings, loadStreak } from '@/db/repo.js';
import { getMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import type { Notice, ReminderStatus, ReminderText } from '@/lib/platform/types.js';
import { localTimeZone } from '@/lib/format.js';

let queue: Promise<unknown> = Promise.resolve();

export function syncReminder(now: Date = new Date()): Promise<ReminderStatus> {
  const run = async (): Promise<ReminderStatus> => {
    const settings = await loadSettings();
    const time = settings?.reminderTime ?? null;
    if (time === null) return platform.reminders.schedule(null);
    const notebook = await getActiveNotebook();
    const words = notebook ? await listWords(notebook.id) : [];
    const dueOn = (day: number): number =>
      words.filter(
        (word) => word.progress !== undefined && !word.progress.retired && isDue(word.progress, day),
      ).length;
    // The server sends come-back to an install it can reach; see pushReceives.
    const comeback = !(await getMeta('pushReceives'));
    return platform.reminders.schedule(
      planReminders({ time, now, timeZone: localTimeZone(), streak: await loadStreak(), dueOn, comeback }),
    );
  };
  const turn = queue.then(run, run);
  queue = turn.catch(() => undefined);
  return turn;
}

/**
 * How far ahead the daily reminders are written. A week: long enough that a
 * phone left alone over a holiday still hears from the notebook every day,
 * short enough that the counts in it are still a fair forecast.
 */
export const DAILY_AHEAD = 7;

/**
 * Days without opening the app after which the reminder changes its tone,
 * and the two last nudges after the daily ones stop. After a month the app
 * goes quiet: somebody who has not come back in thirty days has decided,
 * and a notebook that keeps asking is one that gets uninstalled.
 */
export const COMEBACK_DAYS = [3, 7, 14, 30] as const;

/** Tonight's streak nudge, when the daily reminder does not already fall in the evening. */
export const STREAK_NUDGE_AT = '21:30';

/** A daily reminder at or after this hour carries the streak nudge itself. */
const EVENING_FROM = 19;

/** The shortest streak worth defending out loud. A one-day streak is just yesterday. */
const STREAK_WORTH_SAVING = 2;

/** Id blocks within the host's reminder range (1–20). */
const DAILY_ID = 1; // 1–7: today and the six days after
const COMEBACK_ID = 8; // 8–10: the day 7, 14 and 30 nudges
const STREAK_ID = 11;

/** The lines a quiet day rotates through, so the nudge does not wear out. */
const LINES = [
  'reminder.line1',
  'reminder.line2',
  'reminder.line3',
  'reminder.line4',
  'reminder.line5',
] as const;

export interface PlanInput {
  /** The daily reminder time, "HH:mm" in local time. */
  time: string;
  now: Date;
  timeZone: string;
  streak: Streak;
  /** How many words will be due on a local day index. */
  dueOn: (day: number) => number;
  /**
   * Whether this plan carries the come-back nudges. False when the server
   * can reach this install and sends them itself. Absent means true.
   */
  comeback?: boolean;
}

/**
 * The notifications for the days ahead, written fresh from local data.
 *
 * - One reminder a day for a week, at the chosen time, each saying what that
 *   day holds. A reminder that has already passed today is left out.
 * - On the third day of not opening the app, and on the seventh, fourteenth
 *   and thirtieth, the reminder says so instead. Opening the app rebuilds the
 *   plan from that day, so somebody who uses it never sees these.
 * - A streak of two or more days that today has not yet kept gets an evening
 *   nudge. If today's reminder already falls in the evening it says it; if
 *   not, one more notification comes at half past nine.
 */
export function planReminders({ time, now, timeZone, streak, dueOn, comeback = true }: PlanInput): Notice[] {
  const [hours = 0, minutes = 0] = time.split(':').map(Number);
  const today = dayIndex(now, timeZone);
  const at = (offset: number, h = hours, m = minutes): Date =>
    new Date(now.getFullYear(), now.getMonth(), now.getDate() + offset, h, m, 0, 0);
  const title = t('reminder.title');
  const plan: Notice[] = [];

  const current = effectiveStreak(streak, today);
  const atRisk = current >= STREAK_WORTH_SAVING && !activeToday(streak, today);
  const streakText: ReminderText = { title, body: t('reminder.streak', { count: current }) };

  for (let offset = 0; offset < DAILY_AHEAD; offset += 1) {
    const when = at(offset);
    if (when.getTime() <= now.getTime()) continue;
    const day = today + offset;
    let text: ReminderText;
    if (offset === 0 && atRisk && hours >= EVENING_FROM) text = streakText;
    else if (comeback && offset === COMEBACK_DAYS[0]) text = comebackText(dueOn(day));
    else text = dailyText(day, dueOn(day));
    plan.push({ id: DAILY_ID + offset, at: when, ...text });
  }

  if (comeback) {
    COMEBACK_DAYS.slice(1).forEach((offset, index) => {
      plan.push({ id: COMEBACK_ID + index, at: at(offset), ...comebackText(dueOn(today + offset)) });
    });
  }

  if (atRisk && hours < EVENING_FROM) {
    const [nudgeHours = 21, nudgeMinutes = 30] = STREAK_NUDGE_AT.split(':').map(Number);
    const when = at(0, nudgeHours, nudgeMinutes);
    if (when.getTime() > now.getTime()) plan.push({ id: STREAK_ID, at: when, ...streakText });
  }

  return plan;
}

/** What an ordinary day's reminder says: the count when there is one, else the day's line. */
function dailyText(day: number, due: number): ReminderText {
  const title = t('reminder.title');
  if (due === 1) return { title, body: t('reminder.dueOne') };
  if (due > 1) return { title, body: t('reminder.due', { count: due }) };
  const line = LINES[((day % LINES.length) + LINES.length) % LINES.length] ?? 'reminder.line1';
  return { title, body: t(line) };
}

/** What a reminder says to somebody who has been away. */
function comebackText(due: number): ReminderText {
  const title = t('reminder.title');
  if (due === 1) return { title, body: t('reminder.comebackOne') };
  if (due > 1) return { title, body: t('reminder.comeback', { count: due }) };
  return { title, body: t('reminder.comebackQuiet') };
}
