import { syncReminder } from '@/sync/reminder.js';
import { enablePush } from '@/features/auth/session.js';
import type { ReminderStatus } from '@/lib/platform/types.js';

/** The reminder helper, re-exported so screens import it from their own area. */
export { syncReminder };

/**
 * The time a reminder starts at when somebody turns it on without choosing
 * one: early evening, when a day's reading is done and there is still time
 * to practise before the streak counts.
 */
export const DEFAULT_REMINDER_TIME = '20:00';

/**
 * Schedules a reminder the learner has just turned on, then registers this
 * phone for server notifications under the permission that reminder was
 * given. Come-back nudges follow the reminder, so this is the moment that
 * makes sense of them; a refused reminder asks nothing more.
 */
export async function startReminder(): Promise<ReminderStatus> {
  const status = await syncReminder();
  if (status === 'scheduled') await enablePush().catch(() => undefined);
  return status;
}
