/**
 * Where Settings and its pages live. Settings is a short list of rows, each
 * opening one page, the way a phone's own settings work; every page is a
 * real address so the back button, Android's back key, an iPhone's swipe
 * and a link from a notification or an e-mail all land where they should.
 */
export const SETTINGS_ROOT = '/settings';

/** The pages under Settings, by the last part of their address. */
export const SETTINGS_PAGES = [
  'account',
  'notebooks',
  'practice',
  'notifications',
  'appearance',
  'connected-apps',
  'everywhere',
  'data',
  'plan',
  'about',
  // Only inside the desktop app (Settings shows its row nowhere else).
  'desktop',
] as const;

export type SettingsPageId = (typeof SETTINGS_PAGES)[number];

/** The address of one page under Settings. */
export function settingsPath(page: SettingsPageId): string {
  return `${SETTINGS_ROOT}/${page}`;
}
