/**
 * What the browser extension asks for when it opens /connect-extension in
 * its browser's sign-in window (extension 0.3.0 and later), read and checked
 * before anything is shown or minted.
 *
 * The extension signs in the way the desktop app does (desktopRequest.ts),
 * with the redirect its browser gives it for exactly this:
 * `identity.launchWebAuthFlow` opens
 *
 *   /connect-extension?redirect_uri=https://<id>.chromiumapp.org/
 *                     &state=…&code_challenge=…&code_challenge_method=S256
 *
 * in a window of the browser's own and watches it. When the learner allows
 * it, this page asks the API for a one-time code bound to the challenge and
 * the address and sends the window there with the code and the state. The
 * browser stops that navigation and hands the address to the extension and
 * to nothing else; the code is useless without the verifier, which never
 * left the extension's background.
 *
 * The address is checked here for its shape (Chrome, Edge, Brave and Opera:
 * `https://<32 letters a-p>.chromiumapp.org/`; Firefox:
 * `https://<40 hex>.extensions.allizom.org/`, the SHA-1 of the add-on id),
 * so a bad link never redirects. Whose extension it is, the API decides
 * against its allow-list (`domain/auth.CheckExtensionRedirect` in
 * `lexpad_back`) before any code exists; keep the two shapes in step.
 */

/** An extension's identity redirect URL. Mirrors the API's shape rule. */
const REDIRECT = /^https:\/\/([a-p]{32}\.chromiumapp\.org|[0-9a-f]{40}\.extensions\.allizom\.org)\/$/;

/** An S256 challenge is the base64url of a SHA-256 digest: always 43 characters. */
const CHALLENGE = /^[A-Za-z0-9_-]{43}$/;

/** The extension's state: random, echoed back as it came, nothing that needs escaping. */
const STATE = /^[A-Za-z0-9._~-]{16,256}$/;

export interface ExtensionRequest {
  redirectUri: string;
  state: string;
  codeChallenge: string;
}

/** Whether `raw` has the shape of a browser extension's identity redirect. */
export function isExtensionRedirect(raw: string): boolean {
  return REDIRECT.test(raw);
}

/**
 * The code request in the page's address: the request itself, `'invalid'`
 * when the address asks for a code but any part of it is wrong, or
 * undefined when it does not ask for one (extension 0.2.x, which opens this
 * page with `state` and `key` for the sealed handoff).
 */
export function readExtensionRequest(params: URLSearchParams): ExtensionRequest | 'invalid' | undefined {
  if (!params.has('redirect_uri') && !params.has('code_challenge')) return undefined;
  const redirectUri = params.get('redirect_uri') ?? '';
  const state = params.get('state') ?? '';
  const codeChallenge = params.get('code_challenge') ?? '';
  const method = params.get('code_challenge_method') ?? '';
  if (!isExtensionRedirect(redirectUri) || !STATE.test(state) || !CHALLENGE.test(codeChallenge))
    return 'invalid';
  // "plain" would put the verifier itself in this address.
  if (method !== 'S256') return 'invalid';
  return { redirectUri, state, codeChallenge };
}

/**
 * The address to send the window to: the extension's redirect with the
 * answer and its state, checked once more so a mistake elsewhere cannot make
 * it an open redirect.
 */
export function extensionRedirectUrl(
  request: ExtensionRequest,
  answer: Record<string, string>,
): string | undefined {
  if (!isExtensionRedirect(request.redirectUri)) return undefined;
  const query = new URLSearchParams({ ...answer, state: request.state });
  return `${request.redirectUri}?${query.toString()}`;
}
