import { Outlet, useLocation } from 'react-router-dom';
import { cx } from '@/lib/cx.js';
import { atLeast, useWindowClass } from '@/lib/windowClass.js';
import { Navigation } from './Navigation.js';
import { UpdateGate } from './UpdateGate.js';
import { UpdateToast } from './UpdateToast.js';
import styles from './App.module.css';

/** Routes that own the whole viewport and hide the tab bar. */
const FULL_SCREEN = [/^\/session/, /^\/auth/, /^\/welcome/];

/** The app frame: the routed screen, plus navigation where it belongs. */
export function App(): React.JSX.Element {
  const { pathname } = useLocation();
  const chromeless = FULL_SCREEN.some((pattern) => pattern.test(pathname));
  // Beside the page, the sidebar comes first in reading and Tab order, as
  // in any desktop app, so the keyboard reaches Add a word without crossing
  // the whole screen. A phone keeps its bar after the page, as it always
  // had it. Both slots are always there, so the page itself never remounts.
  const sidebarFirst = atLeast(useWindowClass(), 'medium');

  // The prototype's outer frame: the page ground edge to edge, and one
  // centred column no wider than a phone that every screen lives inside.
  // On a wider window the rail takes the side and each screen sets its own
  // width inside what is left (see the stylesheet).
  return (
    <div className={cx(styles.frame, !chromeless && styles.besideRail)}>
      <div className={styles.column}>
        <UpdateGate>
          {!chromeless && sidebarFirst && <Navigation />}
          <Outlet />
          {!chromeless && (
            <>
              {!sidebarFirst && <Navigation />}
              <UpdateToast />
            </>
          )}
        </UpdateGate>
      </div>
    </div>
  );
}
