/**
 * What Android's back button does. The app keeps its own history, so back
 * pops it; only from Today, the root, does the button leave the app.
 *
 * A page under Settings that was the first thing opened — from a
 * notification, an e-mailed link or an app link at launch — has no history
 * behind it, and popping would do nothing at all. Back goes up to Settings
 * instead (`{ up: '/settings' }`), as the page's own back control does.
 */
export type BackAction = 'back' | 'exit' | { up: string };

/** A page under Settings, whose parent is Settings itself. */
const SETTINGS_PAGE = /^\/settings\/[^/]+\/?$/;

/**
 * Decides from the current URL hash, which the embedded router owns, and
 * whether this is the first entry of the app's history.
 */
export function backButtonAction(hash: string, firstEntry = false): BackAction {
  const path = hash.replace(/^#/, '').split('?')[0] ?? '';
  if (path === '' || path === '/') return 'exit';
  if (firstEntry && SETTINGS_PAGE.test(path)) return { up: '/settings' };
  return 'back';
}

/**
 * Whether the history has nothing behind the current entry. The router
 * numbers its entries in `history.state.idx`, starting at 0; an entry it
 * did not write (a hash set from outside) has no number and is not the
 * first, because something was there before it.
 */
export function isFirstEntry(state: unknown): boolean {
  return typeof state === 'object' && state !== null && 'idx' in state && state.idx === 0;
}
